package com.example.movie_booking_app.data.model.request

import com.google.gson.annotations.SerializedName

/**
 * Model for each shift item generated by the FE algorithm,
 * to be sent in a bulk POST to the backend.
 */
data class NewShiftRequestItem(
    @SerializedName("staffId") val staffId: String,
    @SerializedName("cinemaId") val cinemaId: String,
    @SerializedName("workDate") val workDate: String,   // "yyyy-MM-dd"
    @SerializedName("shift") val shift: String,          // "Morning" | "Afternoon" | "Evening" | "Night"
    @SerializedName("status") val status: String,
    @SerializedName("isHoliday") val isHoliday: Boolean
)
data class DateRangePayload(
    @SerializedName("startDate") val startDate: String,
    @SerializedName("endDate") val endDate: String
)

data class ShiftConfigPayload(
    @SerializedName("staffPerShift") val staffPerShift: Int
)

data class DateRange(
    @SerializedName("startDate") val startDate: String?,
    @SerializedName("endDate") val endDate: String?
)

/**
 * Wrapper request body for POST /api/manager/staff-shifts/generate
 */
data class GenerateShiftRequest(
    @SerializedName("dateRange") val dateRange: DateRangePayload,
    @SerializedName("config") val config: ShiftConfigPayload,
    @SerializedName("shifts") val shifts: List<NewShiftRequestItem>
)
